INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TSPF-HIS-CONFESSION','Lattafa','His Confession Eau de Parfum 100 ml','العطور','العطور','عطر يناسب أمسية ترتدي لها أفضل ما عندك. تبدأ القرفة دافئة مع انتعاش المندرين والخزامى، ثم يعطي السوسن نعومة بودرية. عندما تهدأ البداية، تبرز الفانيلا والعنبر مع أثر خشبي يناسب العشاء والمناسبات المسائية.','{"nameAr":"لطافة هيس كونفشن · أو دو بارفان رجالي 100 مل","tagline":"حضور واثق ودفء يزداد مع الوقت","productType":"fragrance","size":"100 مل","collection":"beauty","koreanCare":false,"imageType":"photo","benefits":["المقدمة من المندرين والقرفة والخزامى","القلب من السوسن والسرو والجاوي ولمسة زهرية","القاعدة من الفانيلا والتونكا والباتشولي والأرز والبخور والعنبر"],"howToUse":"رُشّ العطر على المعصم أو الرقبة واتركه يجف. اختر عدد الرشّات حسب قوة الرائحة التي تفضّلها.","notes":"للاستخدام الخارجي. راجع قائمة المكونات المطبوعة على العبوة إذا كانت لديك حساسية من العطور.","en":{"name":"His Confession Eau de Parfum 100 ml","tagline":"Quiet confidence, with warmth that unfolds","description":"A polished choice for an evening out. Cinnamon warms a bright opening of mandarin and lavender. Iris softens it with a powdery touch, then vanilla and amber settle into a gently woody finish.","benefits":["Mandarin, cinnamon and lavender at the opening","Iris, cypress and benzoin in the heart","Vanilla, tonka, patchouli, cedar, incense and amber at the base"],"howToUse":"Spray on your wrists or neck and let it dry. Adjust the number of sprays to your preference.","notes":"For external use. Check the ingredient list on the packaging if you are sensitive to fragrances.","size":"100 ml"}}',9600,9600,0,'/media/catalog/TSPF-HIS-CONFESSION-855d8c94bc1f.webp','https://lattafa.com/product/his-confession/','Lattafa',24,1,1) ON CONFLICT(id) DO NOTHING;
