INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TSPF-KHAMRAH','Lattafa','Khamrah Eau de Parfum 100 ml','العطور','العطور','رائحة دافئة تليق بأمسية باردة مع الأصدقاء. تظهر القرفة وجوزة الطيب بوضوح، ثم تأتي حلاوة التمر والبرالين. تستقر الفانيلا وخشب العنبر في النهاية، فتمنح العطر طابعًا حلوًا وغنيًا يناسب من يحب الروائح الدافئة.','{"nameAr":"لطافة خمرة · أو دو بارفان للجنسين 100 مل","tagline":"قرفة دافئة وحلاوة تناسب ليالي الشتاء","productType":"fragrance","size":"100 مل","collection":"beauty","koreanCare":false,"imageType":"photo","benefits":["المقدمة من البرغموت والقرفة وجوزة الطيب","القلب من نفحة التمر والبرالين ومسك الروم وزنبق الوادي","القاعدة من الفانيلا والتونكا المحمصة وخشب العنبر والمرّ والجاوي"],"howToUse":"رُشّ العطر على المعصم أو الرقبة واتركه يجف. اختر عدد الرشّات حسب قوة الرائحة التي تفضّلها.","notes":"للاستخدام الخارجي. راجع قائمة المكونات المطبوعة على العبوة إذا كانت لديك حساسية من العطور. سعر الدفعة الأولى 8.40 د.أ، أقل بـ70% من سعر 28 د.أ المعروض لدى فوغا كلوسيت الأردن في 27 نوفمبر 2026.","en":{"name":"Khamrah Eau de Parfum 100 ml","tagline":"Warm cinnamon and the sweetness of a winter evening","description":"An inviting scent for a cool evening with friends. Cinnamon and nutmeg open into a rich heart of dates and praline. Vanilla and amber wood round it out for anyone who enjoys warm, sweet fragrances.","benefits":["Bergamot, cinnamon and nutmeg at the opening","Dates accord, praline, tuberose and lily of the valley in the heart","Vanilla, roasted tonka, amber wood, myrrh and benzoin at the base"],"howToUse":"Spray on your wrists or neck and let it dry. Adjust the number of sprays to your preference.","notes":"For external use. Check the ingredient list on the packaging if you are sensitive to fragrances. The first batch is priced at 8.40 JOD, 70% below the 28 JOD price listed by VogaCloset Jordan on 27 November 2026.","size":"100 ml"}}',8400,8400,0,'/media/catalog/TSPF-KHAMRAH-ab2202a5c7e5.webp','https://lattafa.com/product/khamrah/','Lattafa',24,1,1) ON CONFLICT(id) DO NOTHING;
