INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TSPF-9AM-FEMME','Afnan','9 AM Pour Femme Eau de Parfum 100 ml','العطور','العطور','يشبه بداية يوم مرتبة وخفيفة. الجريب فروت والمندرين يعطيان أول رشة انتعاشًا، ويظهر توت العليق والكشمش الأسود بحلاوة فاكهية في القلب. المسك في النهاية يترك انطباعًا ناعمًا يناسب العمل والمشاوير النهارية.','{"nameAr":"أفنان 9 AM بور فام · أو دو بارفان نسائي 100 مل","tagline":"انتعاش صباحي ولمسة فاكهية ناعمة","productType":"fragrance","size":"100 مل","collection":"beauty","koreanCare":false,"imageType":"photo","benefits":["المقدمة من المندرين والبرغموت والجريب فروت","القلب من الكشمش الأسود وتوت العليق","القاعدة من المسك والبرتقال والعنبر"],"howToUse":"رُشّ العطر على المعصم أو الرقبة واتركه يجف. اختر عدد الرشّات حسب قوة الرائحة التي تفضّلها.","notes":"للاستخدام الخارجي. راجع قائمة المكونات المطبوعة على العبوة إذا كانت لديك حساسية من العطور. سعر الدفعة الأولى 7.50 د.أ، أقل بـ70% من سعر 25 د.أ المعروض لدى أفنان الأردن في 27 نوفمبر 2026.","en":{"name":"9 AM Pour Femme Eau de Parfum 100 ml","tagline":"A bright morning with soft fruit notes","description":"A fresh, put-together scent for daytime. Grapefruit and mandarin bring brightness, while blackcurrant and raspberry add a gentle fruity sweetness. A soft musk finish suits work or an unhurried morning out.","benefits":["Mandarin, bergamot and grapefruit at the opening","Blackcurrant and raspberry in the heart","Musk, orange and amber at the base"],"howToUse":"Spray on your wrists or neck and let it dry. Adjust the number of sprays to your preference.","notes":"For external use. Check the ingredient list on the packaging if you are sensitive to fragrances. The first batch is priced at 7.50 JOD, 70% below the 25 JOD price listed by Afnan Jordan on 27 November 2026.","size":"100 ml"}}',7500,7500,0,'/media/catalog/TSPF-9AM-FEMME-c927ec6247c1.webp','https://afnan.com/products/9-am-pour-femme','Afnan',24,1,1) ON CONFLICT(id) DO NOTHING;
