INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TSPF-9PM','Afnan','9 PM Eau de Parfum 100 ml','العطور','العطور','عطر لسهرة تحب أن تكون فيها بإطلالة مرتبة وعفوية. التفاح والبرغموت يمنحان البداية حيوية، وتأتي القرفة مع زهر البرتقال قبل أن تظهر الفانيلا والتونكا. خيار لمن يحب العطور المسائية الحلوة بلمسة فاكهية واضحة.','{"nameAr":"أفنان 9 PM · أو دو بارفان رجالي 100 مل","tagline":"تفاح وقرفة لسهرة بطابع حيوي","productType":"fragrance","size":"100 مل","collection":"beauty","koreanCare":false,"imageType":"photo","benefits":["المقدمة من التفاح والبرغموت والقرفة واللافاندين","القلب من زهر البرتقال وزنبق الوادي","القاعدة من الفانيلا والتونكا والعنبر والباتشولي"],"howToUse":"رُشّ العطر على المعصم أو الرقبة واتركه يجف. اختر عدد الرشّات حسب قوة الرائحة التي تفضّلها.","notes":"للاستخدام الخارجي. راجع قائمة المكونات المطبوعة على العبوة إذا كانت لديك حساسية من العطور. سعر الدفعة الأولى 6.00 د.أ، أقل بـ70% من سعر 20 د.أ المعروض لدى أفنان الأردن في 27 نوفمبر 2026.","en":{"name":"9 PM Eau de Parfum 100 ml","tagline":"Apple and cinnamon for an upbeat evening","description":"An evening scent for a dressed-up, easygoing mood. Crisp apple and bergamot lead, then cinnamon and orange blossom give way to a sweet vanilla and tonka finish.","benefits":["Apple, bergamot, cinnamon and lavandin at the opening","Orange blossom and lily of the valley in the heart","Vanilla, tonka, amber and patchouli at the base"],"howToUse":"Spray on your wrists or neck and let it dry. Adjust the number of sprays to your preference.","notes":"For external use. Check the ingredient list on the packaging if you are sensitive to fragrances. The first batch is priced at 6.00 JOD, 70% below the 20 JOD price listed by Afnan Jordan on 27 November 2026.","size":"100 ml"}}',6000,6000,0,'/media/catalog/TSPF-9PM-08479033dda2.webp','https://jordan.afnan.com/products/9-pm','Afnan',24,1,1) ON CONFLICT(id) DO NOTHING;
