INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TSPF-9PM-ELIXIR','Afnan','9 PM Elixir Extrait de Parfum 100 ml','العطور','العطور','لأمسية تفضّل فيها رائحة أعمق. يبدأ الهيل وجوزة الطيب بدفء واضح، ثم تمنح نفحة الجلد واللافاندين العطر طابعًا داكنًا. في النهاية تلطّف الفانيلا حدّة التوابل ويضيف الباتشولي عمقًا يناسب الأجواء الباردة.','{"nameAr":"أفنان 9 PM إلكسير · إكستريت دو بارفان للجنسين 100 مل","tagline":"توابل هادئة وطابع جلدي للمساء","productType":"fragrance","size":"100 مل","collection":"beauty","koreanCare":false,"imageType":"photo","benefits":["المقدمة من جوزة الطيب والإليمي والهيل","القلب من البيمنتو واللافاندين ونفحة الجلد","القاعدة من اللابدانوم والباتشولي والفانيلا"],"howToUse":"رُشّ العطر على المعصم أو الرقبة واتركه يجف. اختر عدد الرشّات حسب قوة الرائحة التي تفضّلها.","notes":"للاستخدام الخارجي. راجع قائمة المكونات المطبوعة على العبوة إذا كانت لديك حساسية من العطور. سعر الدفعة الأولى 7.50 د.أ، أقل بـ70% من سعر 25 د.أ المعروض لدى أفنان الأردن في 27 نوفمبر 2026.","en":{"name":"9 PM Elixir Extrait de Parfum 100 ml","tagline":"Warm spices and a leather note for the evening","description":"A deeper scent for an evening out. Cardamom and nutmeg bring early warmth, followed by an aromatic leather heart. Vanilla softens the spice, while patchouli adds depth for cooler nights.","benefits":["Nutmeg, elemi and cardamom at the opening","Pimento, lavandin and leather in the heart","Labdanum, patchouli and vanilla at the base"],"howToUse":"Spray on your wrists or neck and let it dry. Adjust the number of sprays to your preference.","notes":"For external use. Check the ingredient list on the packaging if you are sensitive to fragrances. The first batch is priced at 7.50 JOD, 70% below the 25 JOD price listed by Afnan Jordan on 27 November 2026.","size":"100 ml"}}',7500,7500,0,'/media/catalog/TSPF-9PM-ELIXIR-5a1696d13094.webp','https://jordan.afnan.com/products/9-pm-elixir','Afnan',24,1,1) ON CONFLICT(id) DO NOTHING;
